"Нарисовать схему дома: выходы, безопасное место и сборный пункт.": "Draw a plan of the house: exits, a safe place and a meeting point.",
"Нарисуй карту своего путешествия: линию пути, остановки и значки. Выбери цвет и кисть или поставь готовые значки.": "Draw a map of your trip: the line of the route, the stops and icons. Choose a colour and a brush, or place ready-made icons.",
"Нарисуй карту: добавь хотя бы несколько линий или значков.": "Draw a map: add at least a few lines or icons.",
"Нарисуй схему квартиры или дома: выходы, безопасные места и значки. Выбери цвет и кисть или поставь готовые значки.": "Draw a plan of your apartment or house: exits, safe places and icons. Choose a colour and a brush, or place ready-made icons.",
