"Народное имя «Улы Дала ел» говорит только о прошлом Родины.": "The people's name \"Uly Dala El\" speaks only about the past of the Motherland.",
"Народное имя отражает настоящее, прошлое и будущее нашей Родины.": "The people's name reflects the present, past and future of our Motherland.",
