"Турксиб соединил Среднюю Азию и Казахстан с Сибирью.": "The Turksib connected Central Asia and Kazakhstan with Siberia.",
"Ты помогаешь семье подготовиться к опасным ситуациям: природным катаклизмам и рискам дома. Нужно продумать правила, нужные вещи и план действий. Время и бюджет ограничены, поэтому выбирай с умом.": "You are helping a family prepare for dangerous situations: natural disasters and risks at home. You need to think through rules, necessary things and an action plan. Time and budget are limited, so choose wisely.",
"Ты прошёл все шаги: изучил, спроектировал, сделал, защитил и подвёл итоги. Подготовленная семья действует спокойно и уверенно, и твой план в этом помогает.": "You have gone through all the steps: you studied, designed, made, defended and summed up. A prepared family acts calmly and confidently, and your plan helps with that.",
"Ты прошёл все шаги: изучил, спроектировал, сделал, защитил и подвёл итоги. Так работают гиды и организаторы путешествий. Умение планировать и заботиться о безопасности пригодится тебе всегда.": "You have gone through all the steps: you studied, designed, made, defended and summed up. This is how guides and travel organizers work. The skill of planning and caring about safety will always be useful to you.",
"Ты разрабатываешь маршрут для семьи туристов. Нужно выбрать, куда поехать, на чём добираться, где остановиться и как вести себя безопасно. Время и бюджет ограничены, поэтому выбирай с умом.": "You are developing a route for a family of tourists. You need to choose where to go, how to get there, where to stay and how to behave safely. Time and budget are limited, so choose wisely.",
