"Басқа адамдардың да құқығы бар": "Other people have rights too",
"Құқық қай тақырыпқа жатады?": "Which topic does the right belong to?",
"Өмір, үй және сөз": "Life, home and word",
"Мүлік және өз ісің": "Property and your own business",
"Әркімге туған кезінен тиесілі": "It belongs to everyone from birth",
