"Үйден тек сот шешімімен айыруға болады": "A person can be deprived of their home only by a court decision",
"Сөз бен шығармашылық еркіндігі": "Freedom of speech and creativity",
"Цензураға тыйым салынған": "Censorship is forbidden",
"Мүлікті жекеменшікте ұстау": "Private ownership of property",
"Кез келген заңды түрде алынған": "Anything acquired legally",
"Бизнес-фирма ашу": "Open a business firm",
"Өз ісің": "One's own business",
"Тауар немесе қызмет өндіру": "To produce goods or services",
"Кәсіпкерлік қызмет": "Business activity",
"Бейбіт жиналыстар мен митингілер": "Peaceful gatherings and rallies",
"Қарусыз": "Without weapons",
"Сайлау": "Elections",
"Республикалық референдумға қатысу": "To take part in a national referendum",
"Ел азаматтарының дауыс беруі": "A vote by all citizens of the country",
"Қазақстан азаматтарының құқықтары мен міндеттері қайда жазылған?": "Where are the rights and duties of the citizens of Kazakhstan written down?",
"Қазақстан Республикасының Конституциясында": "In the Constitution of the Republic of Kazakhstan",
"Мектеп жарғысында": "In the school charter",
"Үй сатып алу шартында": "In the contract for buying a home",
"Жол жүру ережелерінде": "In the rules of the road",
"Еліміздегі азаматтардың құқықтары мен міндеттері Конституцияда жазылған.": "The rights and duties of citizens of our country are written in the Constitution.",
"Адам құқықтары мен бостандықтары адамға қашаннан бастап тиесілі?": "From what moment do rights and freedoms belong to a person?",
