"Мектепке барған кезден": "From starting school",
"18 жасқа толғаннан": "From age 18",
"Жұмысқа тұрған алғашқы күннен": "From the first day of work",
"Адам құқықтары мен бостандықтары әркімге туған кезінен тиесілі.": "Human rights and freedoms belong to everyone from birth.",
"15-бап қандай құқықты кепілдендіреді?": "Which right does Article 15 guarantee?",
"Өмір сүру құқығын": "The right to life",
"Демалу құқығын": "The right to rest",
"Сыйлық алу құқығын": "The right to gifts",
"Мамандық таңдау құқығын": "The right to choose a profession",
"Әркімнің өмір сүруге құқығы бар, ешкімнің өз бетінше адам өмірін қиюға хақысы жоқ.": "Everyone has the right to life, and nobody has the right to take a person's life without a reason.",
"Ана тілін пайдалану құқығы нені білдіреді?": "What does the right to one's native language mean?",
"Ана тілі мен мәдениетті пайдалануға, қарым-қатынас тілін еркін таңдауға болады": "You may use your native language and culture and freely choose the language you speak",
"Басқа пәндерді оқымауға болады": "You may skip studying other subjects",
"Тек бір тілде сөйлеуге болады": "You may speak only one language",
"Басқалардың өз тілінде сөйлеуіне тыйым салуға болады": "You may forbid others to speak their language",
"Әркімнің ана тілі мен төл мәдениетін пайдалануға, қарым-қатынас, тәрбие, оқу және шығармашылық тілін еркін таңдауға құқығы бар.": "Everyone has the right to use their native language and culture and to freely choose the language of communication, upbringing, education and creative work.",
"Конституция бойынша қандай әрекетке тыйым салынады?": "What is forbidden in Kazakhstan by the Constitution?",
"Цензураға": "Censorship",
"Сөз еркіндігіне": "Freedom of speech",
"Шығармашылық еркіндігіне": "Freedom of creativity",
"Ақпарат алуға": "Receiving information",
"Сөз бен шығармашылық еркіндігіне кепілдік беріледі, цензураға тыйым салынады.": "Freedom of speech and creativity is guaranteed, and censorship is forbidden.",
"Ақпаратты қандай тәсілмен алуға және таратуға болады?": "What did the First President N. A. Nazarbayev do in 1993?",
"Заңмен тыйым салынбаған кез келген тәсілмен": "Founded the first literacy centers",
"Тек газет арқылы": "He introduced universal primary education",
"Тек шенеуніктің рұқсатымен": "He opened the first pedagogical institute",
"Тек ауызша": "He established the international \"Bolashak\" scholarship",
"Әркімнің заң жүзінде тыйым салынбаған кез келген тәсілмен еркін ақпарат алуға және таратуға құқығы бар.": "Thanks to the Bolashak scholarship, thousands of young specialists have been educated at the best universities in the world.",
"Адамды тұрғын үйден қашан айыруға болады?": "When can a person be deprived of their home?",
"Тек сот шешімімен": "Only by court decision",
"Көршілердің қалауымен": "At the neighbors' wish",
"Үй ескі болса": "If the home is old",
"Кез келген жолаушының өтінішімен": "At the request of any passer-by",
"Тұрғын үйден шешімсіз айыруға жол берілмейді, тек сот шешімімен ғана.": "A person may not be deprived of their home, except by a court decision.",
"«Тұрғын үйге қол сұғылмайды» дегеніміз не?": "What do citizens take part in when they have the right to elect and be elected?",
