"Тапсырманы бөтеннің көмегімен орындауға": "Do tasks without anyone's help",
"Тек бір тілде сөйлеуге": "Communicate in only one language",
"Бүгінгі мектеп оқушыларды өздігінен шешім қабылдауға, үш тілде сөйлеуге, қажет ақпаратты өзі іздеп табуға үйретеді.": "A modern school teaches how to work in a team, act correctly in different situations, communicate in three languages and look for information yourself.",
"ХХ ғасырдың басында елде сауатсыз адамдар көп болды, ересектер де сауатсыз еді.": "At the beginning of the 20th century, there were many people in the country who could not read or write, including adults.",
"Сондықтан халықты жаппай сауаттандыру мәселесі қолға алынды.": "That is exactly why the fight against illiteracy began.",
"«Қызыл отауларда» ересек адамдар білім алды.": "Adults studied in the \"red yurts\".",
"Мұнда мыңдаған ересек адам оқуды және жазуды үйренді.": "There thousands of adults learned to read and write.",
"Қазақ тіліндегі алғашқы «Алгебра» оқулығын Әлихан Бөкейханов жазды.": "Alikhan Bukeikhanov wrote the first school algebra textbook in the Kazakh language.",
"«Алгебра» оқулығын Қаныш Сәтбаев жазды, ал Әлихан Бөкейханов «География» оқулығын жазды.": "Kanysh Satpayev wrote the algebra textbook, and Alikhan Bukeikhanov wrote the geography textbook.",
"1928 жылы ашылған мұғалімдерді даярлайтын институтқа кейін Абайдың есімі берілді.": "The pedagogical institute, opened in 1928, was later named after Abai.",
"Бұл институт мұғалімдерді даярлады.": "The institute trained teachers.",
"Гимназия, лицей мен колледждер 1930 жылдан бұрын пайда болды.": "Gymnasiums, lyceums and colleges appeared in Kazakhstan even before 1930.",
"Олар тәуелсіздік жылдарында, 1991 жылдан бастап пайда болды.": "They appeared in the years of independence, starting in 1991.",
"Мектептер компьютермен жабдықталып, интернет жүйесіне қосылды.": "Schools in Kazakhstan were equipped with computers and connected to the Internet.",
"Бұл тәуелсіздік жылдарында болды.": "This happened in the years of independence.",
"«Болашақ» стипендиясы бойынша тек Қазақстанның мектептерінде оқуға болады.": "The \"Bolashak\" scholarship lets you study only at schools in Kazakhstan.",
"Бұл стипендиямен жас мамандар әлемдегі озық университеттерде білім алды.": "With this scholarship, young specialists studied at the best universities in the world.",
"Білім беру пункттері тек қалаларда ашылды.": "Literacy centers were opened only in cities.",
"Олар ауылдар мен қалалардың екеуінде де ашылды.": "They opened in both cities and villages.",
"Бүгінгі мектеп оқушыларды тек бір тілде сөйлеуге үйретеді.": "Today school teaches communication in only one language.",
"Бүгінгі мектеп үш тілде сөйлеуге үйретеді.": "School teaches communication in three languages.",
"Кеңес кезеңіндегі мектептерде еңбекке тәрбиелеуге үлкен көңіл бөлінді.": "In Soviet times, schools paid great attention to work training.",
"Оқушылар тек оқулықпен ғана емес, еңбекпен де айналысты.": "The students learned not only from textbooks but also how to work.",
